<?php require 'includes/functions.php'; $title='Parfumer'; $active='products'; pageHeader($title,$active); $list=$products; $cat=$_GET['category']??''; $max=(int)($_GET['max']??0); $q=trim($_GET['q']??''); $list=array_filter($list,function($p)use($cat,$max,$q){return (!$cat||$p['category']===$cat)&&(!$max||$p['price']<=$max)&&(!$q||stripos($p['name'].' '.$p['description'],$q)!==false);}); ?>
<main id="main"><section class="page-intro"><p class="eyebrow">ESSENCE · PARFUMERIE</p><h1>Vores <em>parfumer.</em></h1><p>Udvalgt med næse, nysgerrighed og kærlighed til det særlige.</p></section><section class="section catalog"><form class="filters" method="get"><label>Søg <input type="search" name="q" value="<?= e($q) ?>" placeholder="Navn eller duft"></label><label>Kategori <select name="category"><option value="">Alle</option><?php foreach(['Til ham','Til hende','Unisex'] as $c): ?><option <?= $cat===$c?'selected':'' ?>><?= e($c) ?></option><?php endforeach ?></select></label><label>Maks. pris <select name="max"><option value="0">Alle priser</option><?php foreach([800,1000,1200] as $m): ?><option value="<?= $m ?>" <?= $max===$m?'selected':'' ?>><?= money($m) ?></option><?php endforeach ?></select></label><button class="button button-small">Filtrér</button></form><?php if(!$list): ?><p>Ingen parfumer matcher dine valg. Prøv et andet filter.</p><?php endif ?><div class="product-grid"><?php foreach($list as $id=>$p): ?><article class="product-card"><a class="product-image" href="product.php?id=<?= e($id) ?>"><img src="<?= e($p['image']) ?>" alt="<?= e($p['name']) ?> parfumeflaske"></a><div class="product-meta"><div><p class="eyebrow"><?= e($p['category']) ?></p><h3><a href="product.php?id=<?= e($id) ?>"><?= e($p['name']) ?></a></h3></div><span><?= money($p['price']) ?></span></div><p class="product-desc"><?= e($p['description']) ?></p><form method="post" action="cart.php"><input type="hidden" name="action" value="add"><input type="hidden" name="id" value="<?= e($id) ?>"><button class="text-link">Læg i kurv +</button></form></article><?php endforeach ?></div></section></main><?php pageFooter(); ?>
